/**
 * Real Geographic India Map Boundaries and State Paths
 * Pre-projected SVG paths and real centroid coordinates for all Indian States and UTs.
 */

export const MAP_DIMENSIONS = {
  width: 800,
  height: 900,
  minLon: 68.0,
  maxLon: 97.5,
  minLat: 6.5,
  maxLat: 37.5
};

export const projectCoordinates = (lon, lat) => {
  if (lon === undefined || lat === undefined || lon === null || lat === null) return [400, 450];
  const x = (lon - 68.0) * (720.0 / (97.5 - 68.0)) + 40.0;
  const y = (37.5 - lat) * (820.0 / (37.5 - 6.5)) + 40.0;
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
};

